


/** Subscription terms shown before an active plan-backed payment link creates a checkout session. */ export type PaymentLinkSubscriptionPreview = { "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Number of billing intervals between recurring charges. Format: int32. */ "billing_interval_count": number; /** Minimum contract term in months, when configured. Format: int32. */ "contract_term_months"?: number; /** Early termination fee, when configured. */ "early_termination_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Plan image shown to the buyer, when configured. */ "plan_image"?: { "alt"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Format: int32. */ "height": number; "url": string; /** Format: int32. */ "width": number; }; /** Plan name shown to the buyer. */ "plan_name": string; /** Recurring total for one billing interval, including line quantities and resolved modifiers. */ "recurring_total_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Setup fee added to the first amount due, when configured. */ "setup_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Number of trial days before the first recurring charge, when configured. Format: int32. */ "trial_period_days"?: number; };
